msg.payload = JSON.stringify({
    motor_state: String(msg.payload || 'OFF'),
    source: 'dashboard',
    timestamp: Date.now()
});
return msg;

const motorState = String(msg.payload.motor_state || 'ON');
const status = String(msg.payload.status || 'NORMAL');
const vibration = Number(msg.payload.vibration || 0);
const lastFaultVibration = context.get('lastFaultVibration') || 0;

if (status === 'FAULT' && vibration > 0) {
    context.set('lastFaultVibration', vibration);
}

if (motorState === 'OFF') {
    const stoppedAt = (context.get('lastFaultVibration') || lastFaultVibration || vibration).toFixed(4);
    msg.payload = '<span style="color:#ca3838;font-weight:bold;">OFF</span><br/><span style="color:#666;">Motor stopped after abnormality at ' + stoppedAt + ' g</span>';
} else {
    msg.payload = '<span style="color:#00b500;font-weight:bold;">ON</span><br/><span style="color:#666;">Motor running normally</span>';
}
return msg;

